CREATE TABLE community_comments(id uuid PRIMARY KEY,work_id uuid NOT NULL REFERENCES community_works(id) ON DELETE CASCADE,author_id uuid NOT NULL REFERENCES users(id),parent_id uuid REFERENCES community_comments(id) ON DELETE SET NULL,content text NOT NULL CHECK(char_length(content) BETWEEN 1 AND 4000),status text NOT NULL CHECK(status IN ('visible','hidden','deleted')),mutation_id text NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,UNIQUE(author_id,mutation_id));
CREATE INDEX community_comments_work_created_idx ON community_comments(work_id,created_at,id);
CREATE TABLE community_comment_reports(id uuid PRIMARY KEY,comment_id uuid NOT NULL REFERENCES community_comments(id) ON DELETE CASCADE,reporter_id uuid NOT NULL REFERENCES users(id),reason_code text NOT NULL,detail text NOT NULL DEFAULT '',status text NOT NULL CHECK(status IN ('open','resolved','dismissed')),created_at timestamptz NOT NULL,UNIQUE(comment_id,reporter_id,reason_code));
CREATE TABLE community_bookmarks(work_id uuid NOT NULL REFERENCES community_works(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at timestamptz NOT NULL,PRIMARY KEY(work_id,user_id));
CREATE TABLE community_collections(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,title text NOT NULL CHECK(char_length(title) BETWEEN 1 AND 160),description text NOT NULL DEFAULT '' CHECK(char_length(description)<=4000),visibility text NOT NULL CHECK(visibility IN ('public','unlisted','private')),revision integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE TABLE community_collection_mutations(collection_id uuid NOT NULL REFERENCES community_collections(id) ON DELETE CASCADE,mutation_id text NOT NULL,request_hash char(64) NOT NULL,resulting_revision integer NOT NULL,created_at timestamptz NOT NULL,PRIMARY KEY(collection_id,mutation_id));
CREATE TABLE community_collection_items(collection_id uuid NOT NULL REFERENCES community_collections(id) ON DELETE CASCADE,work_id uuid NOT NULL REFERENCES community_works(id) ON DELETE CASCADE,sort_order integer NOT NULL CHECK(sort_order>=0),added_at timestamptz NOT NULL,PRIMARY KEY(collection_id,work_id));
CREATE INDEX community_collections_owner_updated_idx ON community_collections(owner_id,updated_at DESC);
